$TotalFiles = 6
$SuccessCount = 0
$FailedFiles = @()

Write-Host "[1/$TotalFiles] Deploying core/nids_analyze.zig..."
$destPath = Join-Path $DeployRoot "core/nids_analyze.zig"

if (Test-Path $destPath) {
    $backupPath = $destPath + ".phase5_backup"
    Copy-Item $destPath $backupPath -Force
    Write-Host "  [OK] Backup created"
}

$content = [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String($FILE_1_B64))
if ($content.Length -ge 3 -and $content[0] -eq 0xFEFF) {
    $content = $content.Substring(1)
}
Set-Content -Path $destPath -Value $content -NoNewline -Encoding UTF8

$lines = (Get-Content $destPath).Count
if ($lines -eq 1603) {
    Write-Host "  [OK] Deployed: $lines lines (expected 1603)"
    $SuccessCount++
} else {
    Write-Host "  [FAIL] Line count mismatch: $lines (expected 1603)" -ForegroundColor Red
    $FailedFiles += "core/nids_analyze.zig"
    $backupPath = $destPath + ".phase5_backup"
    if (Test-Path $backupPath) { Copy-Item $backupPath $destPath -Force }
}

Write-Host "[2/$TotalFiles] Deploying core/nids_capture.zig..."
$destPath = Join-Path $DeployRoot "core/nids_capture.zig"

if (Test-Path $destPath) {
