    if (Test-Path $backupPath) { Copy-Item $backupPath $destPath -Force }
}

Write-Host "[6/$TotalFiles] Deploying .gitignore..."
$destPath = Join-Path $DeployRoot ".gitignore"

if (Test-Path $destPath) {
    $backupPath = $destPath + ".phase5_backup"
    Copy-Item $destPath $backupPath -Force
    Write-Host "  [OK] Backup created"
}

$content = [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String($FILE_6_B64))
if ($content.Length -ge 3 -and $content[0] -eq 0xFEFF) {
    $content = $content.Substring(1)
}
Set-Content -Path $destPath -Value $content -NoNewline -Encoding UTF8

$lines = (Get-Content $destPath).Count
if ($lines -eq 83) {
    Write-Host "  [OK] Deployed: $lines lines (expected 83)"
    $SuccessCount++
} else {
    Write-Host "  [FAIL] Line count mismatch: $lines (expected 83)" -ForegroundColor Red
    $FailedFiles += ".gitignore"
    $backupPath = $destPath + ".phase5_backup"
    if (Test-Path $backupPath) { Copy-Item $backupPath $destPath -Force }
}

# Delete stale phase backup files from git
$BackupFilesDeleted = 0
Get-ChildItem -Path $DeployRoot -Recurse -Filter "*.phase*_backup" | ForEach-Object {
    Remove-Item $_.FullName -Force
    $BackupFilesDeleted++
    Write-Host "  [CLEANUP] Removed: $($_.Name)"
}

if ($FailedFiles.Count -gt 0) {
    Write-Host ""
    Write-Host "[FAIL] Deployment failed for: $($FailedFiles -join ", ")" -ForegroundColor Red
    exit 1
}

Write-Host ""
Write-Host "[BUILD] Running zig build..."
$buildOutput = & zig build 2>&1
$buildExit = $LASTEXITCODE
if ($buildExit -eq 0) {
    Write-Host "[BUILD] SUCCESS - All Phase 5 fixes applied"
} else {
    Write-Host "[BUILD] FAILED - Rolling back all files" -ForegroundColor Red
    $buildOutput | ForEach-Object { Write-Host $_ }
    $bp_1 = Join-Path $DeployRoot "core/nids_analyze.zig" + ".phase5_backup"
    if (Test-Path $bp_1) { Copy-Item $bp_1 (Join-Path $DeployRoot "core/nids_analyze.zig") -Force }
    $bp_2 = Join-Path $DeployRoot "core/nids_capture.zig" + ".phase5_backup"
    if (Test-Path $bp_2) { Copy-Item $bp_2 (Join-Path $DeployRoot "core/nids_capture.zig") -Force }
    $bp_3 = Join-Path $DeployRoot "core/minifilter_reader.zig" + ".phase5_backup"
    if (Test-Path $bp_3) { Copy-Item $bp_3 (Join-Path $DeployRoot "core/minifilter_reader.zig") -Force }
    $bp_4 = Join-Path $DeployRoot "core/windows_capture.zig" + ".phase5_backup"
    if (Test-Path $bp_4) { Copy-Item $bp_4 (Join-Path $DeployRoot "core/windows_capture.zig") -Force }
    $bp_5 = Join-Path $DeployRoot "core/wfp_ioctl.zig" + ".phase5_backup"
    if (Test-Path $bp_5) { Copy-Item $bp_5 (Join-Path $DeployRoot "core/wfp_ioctl.zig") -Force }
    $bp_6 = Join-Path $DeployRoot ".gitignore" + ".phase5_backup"
    if (Test-Path $bp_6) { Copy-Item $bp_6 (Join-Path $DeployRoot ".gitignore") -Force }
    Write-Host "[ROLLBACK] Complete"
    exit 1
}

Write-Host ""
Write-Host "Summary of changes:"
  Write-Host "  F3:  ctrlHandler: added CTRL_C_EVENT(0)+CTRL_SHUTDOWN_EVENT(6) -- CTRL+C now works!"
  Write-Host "  F4:  wfp_ioctl: IP display reversed (LSB-first -> MSB-first) in 5 locations"
  Write-Host "  F5:  windows_capture: comma typo in IP format + reversed IP"
  Write-Host "  L8:  wfp_ioctl: std.log for block/unblock errors and actions"
  Write-Host "  L9:  nids_capture: std.log for analyze error"
  Write-Host "  L10: minifilter_reader: std.log for FilterGetMessage error"
  Write-Host "  L11: nids_analyze: std.log for TCP listen port, startup"
  Write-Host "  C1:  .gitignore: added *.phase*_backup"
  Write-Host "  C2:  Deleted $BackupFilesDeleted stale backup files"

Write-Host ""
Write-Host "Suggested git commands:"
  Write-Host "  git add -A"
  Write-Host "  git commit -m "fix: best practices phase 5 - bug fixes + cleanup""
  Write-Host "  git push"